const DOM_systemMessage=document.getElementById("systemMessage");function sendSystemMessage(str,error){DOM_systemMessage.innerText=str;DOM_systemMessage.style.color=error?"#f00":"#fff";DOM_systemMessage.style.animationDelay=error?"5s":"3s";DOM_systemMessage.style.animationName="none";DOM_systemMessage.offsetHeight;DOM_systemMessage.style.animationName="messageFadeOut"}const DOM_slideImage=document.getElementById("slideImage");DOM_slideImage.addEventListener("error",function(){this.style.display="none";sendSystemMessage('Error loading image "'+slideshow.imgUrls[slideshow.index]+'".',true)},{passive:true});DOM_slideImage.addEventListener("load",function(){if(slideshow.running){this.style.display=""}},{passive:true});const DOM_intervalInput=document.getElementById("intervalInput");DOM_intervalInput.addEventListener("change",outputSave,{passive:true});const DOM_shuffleCheckbox=document.getElementById("shuffleCheckbox");DOM_shuffleCheckbox.addEventListener("change",outputSave,{passive:true});const DOM_shuffleHelp=document.getElementById("shuffleHelp");const DOM_imageSlots=document.getElementById("imageSlots");const DOM_addImageButton=document.getElementById("addImageButton");const DOM_startButton=document.getElementById("startButton");DOM_intervalInput.value=10;DOM_shuffleCheckbox.checked=true;function updateShuffleHelp(){DOM_shuffleHelp.innerText=DOM_shuffleCheckbox.checked?"(numbers correspond to shuffle weight)":"(numbers multiply the display interval for each image)"}updateShuffleHelp();DOM_shuffleCheckbox.addEventListener("change",updateShuffleHelp);function callback_input_urlInput(){if(this.value.indexOf("\n")<0){return}const weight=this.parentNode.querySelector("input.weight").value;const split=this.value.split("\n");this.value=split.shift();let div=this.parentNode;for(const str of split){const newDiv=makeImageInputDiv(str,weight);div.after(newDiv);div=newDiv}div.querySelector("textarea.url").focus()}function callback_click_deleteButton(){this.parentNode.remove()}function makeImageInputDiv(url,weight){const div=document.createElement("div");const urlInput=document.createElement("textarea");urlInput.classList.add("url");urlInput.addEventListener("input",callback_input_urlInput,{passive:true});urlInput.addEventListener("change",outputSave,{passive:true});urlInput.value=url;urlInput.placeholder="https://www.google.com/images/logo.gif";div.appendChild(urlInput);const weightInput=document.createElement("input");weightInput.type="number";weightInput.classList.add("weight");weightInput.addEventListener("change",outputSave,{passive:true});weightInput.value=weight;div.appendChild(weightInput);const deleteButton=document.createElement("button");deleteButton.innerText="X";deleteButton.addEventListener("click",callback_click_deleteButton,{passive:true,once:true});deleteButton.addEventListener("click",outputSave,{passive:true,once:true});div.appendChild(deleteButton);return div}DOM_addImageButton.addEventListener("click",function(){const div=makeImageInputDiv("",1);DOM_imageSlots.appendChild(div);div.querySelector("textarea.url").focus();outputSave()},{passive:true});const slideshow={callback(){let interval=this.interval,src;if(this.shuffle){let weightSum=0;for(let i=this.imgWeights.length-1;i>=0;i-=1){weightSum+=(this.imgWeights[i]+=0.1*this.imgBaseWeights[i])}let pickerValue=Math.random()*weightSum;let pick=0;for(let i=0;i<this.imgWeights.length;i+=1){pickerValue-=this.imgWeights[i];if(pickerValue<0){pick=i;break}}this.imgWeights[pick]=-0.1;this.index=pick;src=this.imgUrls[pick]}else{this.index+=1;this.index%=this.imgUrls.length;src=this.imgUrls[this.index];interval*=this.imgWeights[this.index]}if(src){DOM_slideImage.src=src}else{DOM_slideImage.style.display="none"}if(slideshow.imgBaseWeights[1]&&this.interval<Number.POSITIVE_INFINITY){this.callbackTimeoutId=setTimeout(globalSlideshowCallback,interval)}},stop(){this.running=false;document.body.classList.remove("running");if(this.callbackTimeoutId){clearTimeout(this.callbackTimeoutId)}DOM_slideImage.style.display="none"}};const globalSlideshowCallback=_=>slideshow.callback();function globalSlideshowStop(){slideshow.stop();document.body.removeEventListener("click",globalSlideshowStop);document.body.removeEventListener("keyUp",globalSlideshowStopOnEnter)}function globalSlideshowStopOnEnter(e){if(e.key=="Enter"){globalSlideshowStop()}}DOM_startButton.addEventListener("click",function(){slideshow.imgUrls=[];slideshow.imgWeights=[];for(const div of DOM_imageSlots.children){const weightInput=Number(div.querySelector("input.weight").value);if(weightInput<=0){continue}slideshow.imgUrls.push(div.querySelector("textarea.url").value);slideshow.imgWeights.push(weightInput)}slideshow.imgBaseWeights=[...slideshow.imgWeights];if(slideshow.imgBaseWeights[0]){slideshow.shuffle=DOM_shuffleCheckbox.checked;const interval=Number(DOM_intervalInput.value)*1000;if(interval<=0){slideshow.interval=Number.POSITIVE_INFINITY}else{slideshow.interval=interval}slideshow.index=-1;slideshow.running=true;globalSlideshowCallback()}sendSystemMessage("Running... click anywhere or press enter to reconfigure.");document.body.classList.add("running");requestAnimationFrame(function(){document.body.addEventListener("click",globalSlideshowStop,{passive:true});document.body.addEventListener("keydown",globalSlideshowStopOnEnter,{passive:true})})},{passive:true});const filterInputValue=node=>node.value.replaceAll("\\","/").replaceAll("|","\\|");function outputSave(){let output=window.location.href.split("#")[0]+"#";output+=DOM_shuffleCheckbox.checked?"y|":"n|";output+=filterInputValue(DOM_intervalInput);for(const div of DOM_imageSlots.children){output+="|"+filterInputValue(div.querySelector("textarea.url"))+"|"+filterInputValue(div.querySelector("input.weight"))}window.history.pushState({},"",output)}const urlInputLocation=window.location.href.indexOf("#");if(urlInputLocation>-1){const urlInput=window.location.href.slice(window.location.href.indexOf("#")+1).split(/(?<!\\)\|/);for(let i in urlInput){urlInput[i]=urlInput[i].replaceAll("\\|","|")}if(urlInput[0]&&urlInput.length%2<1){DOM_shuffleCheckbox.checked=urlInput[0]=="y";updateShuffleHelp();DOM_intervalInput.value=Number(urlInput[1]);for(let i=2;i<urlInput.length;i+=2){DOM_imageSlots.appendChild(makeImageInputDiv(urlInput[i],Number(urlInput[i+1])))}}}